import mongoose from 'mongoose';
import bcrypt from 'bcryptjs';

// Platform model: staff identities live outside any tenant. Never registered via
// defineTenantModel and never receives the tenantScoped plugin.
const staffAccountSchema = new mongoose.Schema({
  // _id: ObjectId, auto-generated by mongoose; preserved as-is during migration
  email: { type: String, required: true, unique: true, lowercase: true, trim: true },
  username: { type: String, required: true, trim: true },
  password: { type: String, required: true, select: false },
  status: { type: String, enum: ['active', 'suspended', 'closed'], default: 'active', index: true },
  twoFactor: {
    enabled: { type: Boolean, default: false },
    secretEnc: { type: String, default: null, select: false },
    backupCodesHash: { type: [String], default: [], select: false },
  },
  tokenVersion: { type: Number, default: 0 },
  lastLoginAt: { type: Date, default: null },
  lastLoginIp: { type: String, default: null },
  createdBy: { type: mongoose.Schema.Types.ObjectId, ref: 'StaffAccount', default: null },
}, { timestamps: true });

staffAccountSchema.pre('save', async function() {
  if (this.isModified('password')) this.password = await bcrypt.hash(this.password, 12); // same cost as User
});

staffAccountSchema.methods.comparePassword = function(candidate) {
  return bcrypt.compare(candidate, this.password);
};

// Never leaks password, secretEnc or backupCodesHash, regardless of select().
staffAccountSchema.methods.toSafeObject = function() {
  return {
    id: this._id,
    email: this.email,
    username: this.username,
    status: this.status,
    twoFactorEnabled: !!this.twoFactor?.enabled,
    tokenVersion: this.tokenVersion,
    lastLoginAt: this.lastLoginAt,
  };
};

export default mongoose.model('StaffAccount', staffAccountSchema);
